#nullable enable // autogenerated  

using MVZ2.GameContent.Enemies;
using MVZ2.Vanilla.Entities;
using PVZEngine;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.Vanilla.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.HostMutant)]
    public class HostMutant : MutantZombieBase
    {
        public HostMutant(string nsp, string name) : base(nsp, name)
        {
            SetImpID(VanillaEnemyID.HostIMP);
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);

            // 添加持续回血 Buff  
            entity.InflictRegenerationBuff(1f, 60000, new EntitySourceReference(entity));

            // 初始化记录血量（用于掉血检测）  
            HealthLossSpawnHelper.Init(entity, ID);
        }

        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            // 每损失 800 血，从内置池生成一个单位，最多 2 次  
            HealthLossSpawnHelper.CheckHealthLossTrigger(entity, ID, 800f, 2,
                e => HealthLossSpawnHelper.SpawnWeightedRandom(e, RandomEntity, RandomEntityWeights));
        }

        // 可召唤单位列表（怪物出怪）  
        private static NamespaceID[] RandomEntity = new NamespaceID[]
        {
            VanillaEnemyID.HostZombie,
        };

        private static int[] RandomEntityWeights = new int[]
        {
            1,
        };

        private static readonly NamespaceID ID = VanillaEnemyID.HostMutant;
    }
}
